<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Learning\SkillExperience;
$experience=$core->get('learning_skill_experience');$member=p14_user('install-reader');
wp_set_current_user($admin);$license=$management->saveTerm('tag',null,['name'=>'MIT (synthetic QA evidence)','slug'=>'license-mit-'.$run]);$platform=$management->saveTerm('tag',null,['name'=>'QA platform','slug'=>'platform-qa-'.$run]);
$command="printf '%s\\n' 'QA copy-only example'";
$create=function(string $suffix,bool $licensed=true,bool $repository=false)use($management,$db,$admin,$run,$license,$platform,$command):array{
 wp_set_current_user($admin);$translations=[];foreach(['zh_CN','en_US']as$l)$translations[$l]=['title'=>'Installation QA '.$suffix.' '.$l,'slug'=>'install-'.$run.'-'.$suffix,'summary'=>'Synthetic source-backed installation check','content'=>'<h2>Reviewed example</h2><p>QA only, never execute automatically.</p><pre><code>'.esc_html($command).'</code></pre>'];
 $input=['save_mode'=>'pending','translations'=>$translations,'tag_ids'=>$licensed?[$license,$platform]:[$platform]];
 if($repository){$input['repository_id']=$management->saveRepository(null,'qa-'.$run,'install-'.$suffix);$input['source_path']='skills/example/SKILL.md';}
 $id=$management->saveSkill(null,$input);$management->review($id,'approved','unknown','Synthetic manual content review',p14_skill_revision($id));$version=0;
 if($repository){$source="---\nname: qa-installation\ndescription: Synthetic source fixture.\n---\n\n```sh\n$command\n```\n";$now=gmdate('Y-m-d H:i:s');$commit=hash('sha1',$run.':'.$suffix.':commit');$file=hash('sha1',$source);$version=$db->insert('skill_versions',['skill_id'=>$id,'repository_id'=>$input['repository_id'],'source_path'=>$input['source_path'],'commit_sha'=>$commit,'file_sha'=>$file,'content_hash'=>hash('sha256',$source),'source_content'=>$source,'created_at'=>$now]);$db->insert('imports',['skill_id'=>$id,'repository_id'=>$input['repository_id'],'source_path'=>$input['source_path'],'commit_sha'=>$commit,'file_sha'=>$file,'metadata_json'=>'{}','findings_json'=>'{}','source_status'=>'present','change_status'=>'new','created_at'=>$now,'updated_at'=>$now]);}
 return ['id'=>$id,'version'=>$version,'revision'=>p14_skill_revision($id)];
};
$payload=fn(int $version=0):array=>['state'=>'verified','version_id'=>$version,'commands'=>[['command'=>$command,'platform'=>'platform-qa-'.$run]],'rights_note'=>'Synthetic QA administrator reviewed the source quotation and MIT attribution.'];
p14_case('unverified_copy_is_never_implicitly_enabled',function()use($create,$experience,$member,$payload){$f=$create('unverified');p14_assert($experience->installation($f['id'],'en_US')===['state'=>'unverified','commands'=>[]],'Published code block alone is not copy-authorized');wp_set_current_user($member);p14_reject(fn()=>$experience->save($f['id'],'en_US',$payload(),0,$f['revision'],true),'Ordinary verified subscriber cannot grant installation rights');});
p14_case('reviewed_editorial_copy_is_exact_locale_bound_private_notes_absent',function()use($create,$experience,$payload,$command){$f=$create('manual');$r=$experience->save($f['id'],'en_US',$payload(),0,$f['revision'],true);$a=$experience->installation($f['id'],'en_US');p14_assert($a['state']==='verified'&&$a['kind']==='editorial'&&$a['commands'][0]['command']===$command,'Exact visible reviewed command is a quotation');p14_assert(str_contains($a['source_url'],'/en/skills/')&&str_ends_with($a['source_url'],'#skill-overview'),'Manual evidence points to current public source');p14_assert(!isset($a['rights_note'],$a['actor_id'],$a['binding'],$a['source_content']),'Private reviewer note and source body absent');p14_assert($experience->installation($f['id'],'zh_CN')['state']==='unverified','English review cannot silently certify Chinese copy');p14_assert($experience->save($f['id'],'en_US',$payload(),0,$f['revision'],true)===$r,'Exact save replay is idempotent');p14_reject(fn()=>$experience->save($f['id'],'en_US',array_replace($payload(),['rights_note'=>'Different review intent requires new expected version']),0,$f['revision'],true),'Conflicting stale write rejected');});
p14_case('license_platform_and_visible_source_are_mandatory',function()use($create,$experience,$payload,$command){$f=$create('no-license',false);p14_reject(fn()=>$experience->save($f['id'],'en_US',$payload(),0,$f['revision'],true),'No license cannot authorize clipboard command');$f=$create('strict-evidence');$bad=$payload();$bad['commands'][0]['command']='invented installer command';p14_reject(fn()=>$experience->save($f['id'],'en_US',$bad,0,$f['revision'],true),'Unwritten installation command rejected');$bad=$payload();$bad['commands'][0]['platform']='platform-invented';p14_reject(fn()=>$experience->save($f['id'],'en_US',$bad,0,$f['revision'],true),'Unsupported platform not guessed');p14_reject(fn()=>$experience->save($f['id'],'en_US',$payload(),0,$f['revision'],false),'Explicit rights confirmation required');p14_assert($experience->installation($f['id'],'en_US')['state']==='unverified','Failed saves cannot enable copy');});
p14_case('repository_snapshot_sha_and_source_change_invalidate_copy',function()use($create,$experience,$payload,$db){$f=$create('repository',true,true);$experience->save($f['id'],'en_US',$payload($f['version']),0,$f['revision'],true);$a=$experience->installation($f['id'],'en_US');p14_assert($a['state']==='verified'&&$a['kind']==='repository'&&strlen($a['commit_sha'])===40&&strlen($a['file_sha'])===40,'Verified immutable source snapshot bound');p14_assert(str_contains($a['source_url'],'/blob/'.$a['commit_sha'].'/skills/example/SKILL.md'),'Specific commit source URL, not mutable HEAD');$db->execute('UPDATE '.$db->table('imports').' SET file_sha=%s WHERE skill_id=%d',[str_repeat('f',40),$f['id']]);p14_assert($experience->installation($f['id'],'en_US')['state']==='unverified','Unreviewed upstream file change removes copy evidence immediately');});
p14_case('reviewed_content_change_archive_and_missing_translation_fail_closed',function()use($create,$experience,$payload,$management,$db){$f=$create('stale');$experience->save($f['id'],'en_US',$payload(),0,$f['revision'],true);$management->archiveSkill($f['id'],p14_skill_revision($f['id']));p14_assert($experience->installation($f['id'],'en_US')['state']==='unverified'&&$experience->share($f['id'],'en_US')===[],'Archived resource has neither verified copy nor share');$private=p14_skill('not-reviewed',false);p14_assert($experience->share($private,'en_US')===[],'Draft is not shareable through forged ID');$single=p14_skill('only-english',true,false);p14_assert($experience->share($single,'zh_CN')===[],'Absent translation never shares an invented Chinese URL');});
p14_case('public_share_discards_query_credentials_and_preserves_language',function()use($create,$experience){$f=$create('share',true,true);$_GET=['aish_preview'=>'synthetic-private-token','internal_note'=>'private'];foreach(['zh_CN'=>'/zh/','en_US'=>'/en/']as$locale=>$prefix){$s=$experience->share($f['id'],$locale);p14_assert(str_contains($s['url'],$prefix)&&!str_contains($s['url'],'?')&&!str_contains(wp_json_encode($s),'synthetic-private-token'),'Share uses canonical current public language, not request query');p14_assert(str_starts_with($s['source_url'],'https://github.com/')&&str_contains($s['source_url'],'/SKILL.md'),'GitHub copy uses validated fixed source domain');foreach($s['social']as$url){parse_str((string)parse_url($url,PHP_URL_QUERY),$q);p14_assert(($q['url']??'')===$s['url'],'Social destination has exact public URL');}}$_GET=[];});
p14_case('hidden_controls_markup_substrings_and_duplicate_commands_rejected',function()use($command){foreach(["echo\0hidden","echo\x1b[31mhidden","echo\u{202e}hidden",str_repeat('x',2001)]as$bad)p14_reject(fn()=>SkillExperience::command($bad),'Hidden control or excessive command denied');$html='<pre><code>'.$command.'</code></pre><pre style="display:none"><code>secret</code></pre><pre><code><span>hidden</span></code></pre><div class="hidden"><pre><code>hidden-parent</code></pre></div>';p14_assert(SkillExperience::codeBlocks($html)===[$command],'Only fully visible inert exact command block extracted');p14_assert(!SkillExperience::sourceContains('prefix '.$command.' suffix',$command)&&SkillExperience::sourceContains("before\n$command\nafter",$command),'Complete source line needed; substring insufficient');p14_reject(fn()=>SkillExperience::commands([['command'=>$command,'platform'=>''],['command'=>$command,'platform'=>'']]),'Duplicate clipboard definitions rejected');});
p14_report('Real WordPress/MySQL reviewed installation evidence, source SHA binding, public sharing and transaction/replay guards; synthetic GitHub snapshots, no GitHub request and no command execution');
